<?php
require __DIR__.'/includes/session.php'; require __DIR__.'/includes/admin-layout.php'; require __DIR__.'/includes/admin-data.php';
$account=require_account(true); $error=''; $players=[]; $search=is_string($_GET['q']??null)?trim($_GET['q']):'';
try { $db=spellstorm_database(); if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=field('id'); $role=field('role'); if($id===$account['id'] || !in_array($role,['player','admin'],true) || !preg_match('/\A[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\z/i',$id)) throw new InvalidArgumentException('Choose a valid account other than your own.'); $stmt=$db->prepare('UPDATE public.users SET role=? WHERE id=?'); $stmt->execute([$role,$id]); redirect_to('admin-players.php?saved=1'); } $players=admin_players($db,$search); } catch(InvalidArgumentException $e) { $error=$e->getMessage(); } catch(Throwable $e) { $error='Player data unavailable.'; }
admin_header('Player Management','players',$account); ?>
<p>Search registered accounts and inspect player roles.</p><?php if($error): ?><p class="error"><?=escape($error)?></p><?php endif; ?>
<section class="admin-panel"><form method="get" class="d-flex gap-2 mb-3"><input class="form-control" name="q" aria-label="Search players" placeholder="Username or email" value="<?=escape($search)?>"><button class="btn btn-primary">Search</button><a class="btn btn-outline-light" href="admin-players.php">Reset</a></form><?php if(isset($_GET['saved'])): ?><p role="status">Role updated.</p><?php endif; ?><?php if(!$players): ?><p>No matching accounts.</p><?php else: ?><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Username</th><th>Email</th><th>Role</th><th>Registered</th><th>Action</th></tr></thead><tbody><?php foreach($players as $player): ?><tr><?php foreach(['username','email','role','created_at'] as $key): ?><td><?=escape((string)$player[$key])?></td><?php endforeach; ?><td><?php if($player['id']!==$account['id']): ?><form method="post" onsubmit="return confirm('Change this account role?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=escape($player['id'])?>"><input type="hidden" name="role" value="<?=$player['role']==='admin'?'player':'admin'?>"><button class="btn btn-sm btn-outline-light"><?=$player['role']==='admin'?'Make player':'Make admin'?></button></form><?php else: ?>Current account<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php admin_footer(); ?>
